<?php
declare(strict_types=1);
function admin_user(): ?array { $u=current_user(); if(!$u || ($u['role']??'')!=='admin') return null; return ['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>'owner']; }
function require_admin(): void { if (!admin_user()) { header('Location: '.rtrim(APP_URL,'/').'/web/index.php'); exit; } }
function admin_can(string $minimum='editor'): bool { return admin_user()!==null; }
function setting(string $key, string $default=''): string { global $pdo; static $cache=[]; if(array_key_exists($key,$cache)) return $cache[$key]; try{$s=$pdo->prepare('SELECT setting_value FROM site_settings WHERE setting_key=? LIMIT 1');$s->execute([$key]);$v=$s->fetchColumn();$cache[$key]=($v===false||$v===null)?$default:(string)$v;}catch(Throwable $e){$cache[$key]=$default;} return $cache[$key]; }
function save_setting(string $key, string $value): void { global $pdo; $s=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute([$key,$value]); }
function log_admin(string $action, string $details=''): void { global $pdo; try{$s=$pdo->prepare('INSERT INTO admin_activity(admin_email,action,details) VALUES(?,?,?)');$s->execute([admin_user()['email']??'unknown',$action,mb_substr($details,0,4000)]);}catch(Throwable $e){} }
function safe_upload(string $field, string $folder, array $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif']): ?string { if(empty($_FILES[$field])||($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null; $f=$_FILES[$field]; if($f['error']!==UPLOAD_ERR_OK||$f['size']>8*1024*1024)throw new RuntimeException('Upload failed or file exceeds 8 MB.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); if(!isset($allowed[$mime])||!@getimagesize($f['tmp_name']))throw new RuntimeException('Only valid JPG, PNG, WebP or GIF images are allowed.'); $dir=dirname(__DIR__).'/uploads/'.$folder; if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Upload directory could not be created.'); $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not save uploaded image.'); return 'uploads/'.$folder.'/'.$name; }
function public_asset(string $path): string { if($path==='' || preg_match('~^https?://~i',$path) || str_starts_with($path,'data:') || str_starts_with($path,'/')) return $path; return str_starts_with($path,'uploads/') ? '../'.$path : $path; }
function valid_https_url(string $url): bool { return filter_var($url,FILTER_VALIDATE_URL)!==false && strtolower((string)parse_url($url,PHP_URL_SCHEME))==='https'; }
function track_event(string $type, ?string $path=null): void { global $pdo; if(!in_array($type,['page_view','login','booking_submit','gallery_open','social_click'],true))return; if(session_status()!==PHP_SESSION_ACTIVE)return; if(empty($_SESSION['_visitor_key']))$_SESSION['_visitor_key']=bin2hex(random_bytes(24)); $sid=hash('sha256',session_id()); $vk=hash('sha256',$_SESSION['_visitor_key']); try{$q=$pdo->prepare('INSERT INTO site_events(event_type,page_path,session_key,visitor_key,user_id) SELECT ?,?,?,?,? WHERE NOT EXISTS (SELECT 1 FROM site_events WHERE session_key=? AND event_type=? AND page_path <=> ? AND created_at > NOW() - INTERVAL 30 SECOND)');$q->execute([$type,mb_substr($path??'',0,500),$sid,$vk,$_SESSION['user_id']??null,$sid,$type,mb_substr($path??'',0,500)]);}catch(Throwable $e){} }
